SELECT to_regclass('public.product_color_sizes') AS size_table,
       to_regclass('public.excel_catalogue_imports') AS import_ledger,
       to_regclass('public.excel_catalogue_batches') AS batch_ledger,
       to_regclass('public.excel_catalogue_batch_audit') AS variant_receipts,
       to_regprocedure('public.pos_change_variant_stock(uuid,uuid,uuid,integer,boolean)') AS stock_writer,
       to_regprocedure('public.apply_excel_catalogue(jsonb)') AS import_writer;
SELECT table_name,column_name,data_type,is_nullable
FROM information_schema.columns WHERE table_schema='public'
AND (table_name='product_color_sizes' OR (table_name='products' AND column_name='stock_tracking_mode'))
ORDER BY table_name,ordinal_position;
SELECT tgrelid::regclass AS relation,tgname,tgenabled,pg_get_triggerdef(oid) AS definition
FROM pg_trigger WHERE NOT tgisinternal AND tgrelid IN
(to_regclass('public.product_color_sizes'),to_regclass('public.product_colors'),to_regclass('public.stock_movements'));

