  WHERE e->>'code' <> 'LB-532'
), received AS (
  SELECT x.code,x.source_row,a.batch_id,
    a.product_code=x.code AND a.product_id=l.product_id AND a.outcome='IMPORTED'
      AND x.variants=(SELECT jsonb_agg(jsonb_build_array(v->>'colour',(v->>'approved_quantity')::int)
        ORDER BY v->>'colour') FROM jsonb_array_elements(a.variants) v)
      AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(a.variants) v
        WHERE v->'approved_quantity' IS DISTINCT FROM v->'committed_quantity'
        OR v->'approved_delta' IS DISTINCT FROM v->'stock_quantity_applied') AS matches
  FROM expected x
  LEFT JOIN public.excel_catalogue_imports l
    ON l.workbook_sha256='a299523b77936493abe5079d45a1687b6405ec75a4d0fcc3b0a832d54dc89aa5' AND l.sheet_name='CN Working Sheet' AND l.source_row=x.source_row
  LEFT JOIN public.excel_catalogue_batch_audit a ON a.application_id=l.application_id AND a.outcome='IMPORTED'
)
SELECT code,source_row,batch_id,coalesce(matches,false) AS matches_committed_receipt
FROM received ORDER BY source_row;

WITH seed AS (
  SELECT * FROM jsonb_to_recordset($shoes$[{"code":"SS-6008","slug":"ss-6008-428b3a735bb5"},{"code":"SS- SC","slug":"ss-sc-616e40f1008c"},{"code":"SS-DC","slug":"ss-dc-b03f14a2b1f7"},{"code":"LSS- 6H061","slug":"lss-6h061-2766a10da940"}]$shoes$::jsonb) AS x(code text,slug text)
)
SELECT s.code,p.id AS existing_product_id,p.barcode AS existing_code,p.name AS existing_name,
       p.slug AS existing_slug,p.base_price,p.stock_tracking_mode,
       (SELECT jsonb_agg(jsonb_build_object('id',c.id,'colour',c.color_name,'quantity',c.stock_quantity,
         'sizes',(SELECT jsonb_agg(jsonb_build_object('id',z.id,'system',z.size_system,'label',z.size_label,
                   'quantity',z.stock_quantity,'archived',z.archived) ORDER BY z.size_label)
                  FROM public.product_color_sizes z WHERE z.color_id=c.id)) ORDER BY c.id)
        FROM public.product_colors c WHERE c.product_id=p.id) AS existing_inventory
FROM seed s LEFT JOIN public.products p
ON lower(regexp_replace(btrim(p.barcode),'[[:space:]]+','','g')) =
   lower(regexp_replace(btrim(s.code),'[[:space:]]+','','g')) OR p.slug=s.slug
ORDER BY s.code,p.id;

ROLLBACK;
